129:   connectStream() {
130:     if (typeof EventSource === 'undefined') return
131:     try {
132:       this.stream = new EventSource(`/api/stream?clientId=${encodeURIComponent(this.clientId)}`)
133:       this.stream.onmessage = (event) => {
