151:   handleEvent(payload) {
152:     if (payload.type === 'hello') {
153:       this.provider = payload.provider || this.provider
154:       this.el.provider.textContent = payload.provider?.provider === 'zen' ? `AI ${payload.provider.model}` : 'CITY AI'
155:       return
156:     }
157:     if (payload.type === 'message') {
158:       const message = payload.message
159:       if (!message) return
160:       if (this.mode === 'room' && message.roomId === this.room?.id) {
161:         this.messages.push(message)
162:         this.renderMessages()
163:       }
164:       return
165:     }
166:     if (payload.type === 'presence') {
167:       if (this.mode === 'room' && payload.roomId === this.room?.id) {
168:         const others = (payload.names || []).filter((name) => name !== this.playerName)
169:         this.el.presence.textContent = others.length
170:           ? `${payload.humans} here · ${others.join(', ')}`
171:           : `${payload.humans} here`
172:       }
173:       return
174:     }
175:     if (payload.type === 'mission_update') {
176:       if (payload.clientId && payload.clientId !== this.clientId) return
177:       this.activeMission = payload.mission || null
178:       this.onMission(this.activeMission)
179:       if (payload.note === 'accepted') this.onToast('Job accepted — your crew is rolling')
180:       return
181:     }
182:   }
