195:     this.el.presence.textContent = `${target.humans || 0} here`
196:     this.el.boardBtn.classList.toggle('is-hidden', !target.board)
197:     this.el.panel.classList.remove('is-hidden')
198:     this.el.input.placeholder = `Say something in ${target.name}...`
199:     this.renderMembers(target.members || [])
200:     this.renderChips(CHIPS.default)
