202: 
203:     try {
204:       const res = await fetch('/api/room/join', {
205:         method: 'POST',
206:         headers: { 'Content-Type': 'application/json' },
207:         body: JSON.stringify({ clientId: this.clientId, roomId: target.id, name: this.playerName })
208:       })
209:       const body = await res.json()
210:       if (body.room) {
211:         this.room = { ...target, ...body.room, members: target.members }
212:         this.el.presence.textContent = `${body.humans || 0} here`
213:       }
214:       const history = await (await fetch(`/api/room/${target.id}`)).json()
215:       this.messages = history.messages || []
