223:   enterDm(persona, anchor = null) {
224:     this.mode = 'dm'
225:     this.room = { id: `dm-${persona.id}`, name: persona.name, topic: persona.blurb, accent: persona.color, members: [persona] }
226:     this.dmPersona = persona
