233:     this.el.boardBtn.classList.add('is-hidden')
234:     this.el.panel.classList.remove('is-hidden')
235:     this.el.input.placeholder = `Talk to ${persona.name}...`
236:     this.renderMembers([persona])
237:     this.renderChips(CHIPS.default)
238:     this.pushLocal({ kind: 'system', text: `You step aside and talk to ${persona.name}.`, author: { name: 'Sunset City', color: '#8aa0b8' } })
239:     this.pushOpen()
