243:   async greet(persona, anchor) {
244:     try {
245:       const res = await fetch('/api/chat', {
246:         method: 'POST',
247:         headers: { 'Content-Type': 'application/json' },
248:         body: JSON.stringify({
249:           clientId: this.clientId,
250:           roomId: `dm-${persona.id}`,
251:           target: persona.id,
252:           text: 'hey'
253:         })
254:       })
255:       const body = await res.json()
256:       if (body.reply) {
257:         this.pushLocal(body.reply)
258:         if (anchor) this.say(anchor, persona.name, body.reply.text, persona.color)
259:       }
260:     } catch {
261:       /* hub offline */
262:     }
263:   }
