265:   exitRoom() {
266:     if (this.mode === 'closed') return
267:     if (this.mode === 'room' && this.room) {
268:       fetch('/api/room/leave', {
269:         method: 'POST',
270:         headers: { 'Content-Type': 'application/json' },
271:         body: JSON.stringify({ clientId: this.clientId, roomId: this.room.id })
272:       }).catch(() => {})
273:     }
274:     this.mode = 'closed'
275:     this.room = null
276:     this.dmPersona = null
277:     this.messages = []
278:     this.el.panel.classList.add('is-hidden')
279:     this.el.log.innerHTML = ''
280:     this.popOpen()
281:   }
282: 
283:   pushOpen() {
284:     this.openCount = (this.openCount || 0) + 1
285:     document.body.classList.add('social-open')
286:     this.onOpenRoom(this.room)
287:   }
288: 
289:   popOpen() {
290:     this.openCount = Math.max(0, (this.openCount || 0) - 1)
291:     if (this.openCount > 0) return
292:     document.body.classList.remove('social-open')
293:     this.onClose()
294:   }
295: 
296:   renderMembers(members) {
297:     this.el.members.innerHTML = ''
298:     for (const member of members || []) {
299:       if (!member || !member.name) continue
300:       const chip = document.createElement('span')
301:       chip.className = 'member-chip'
302:       chip.innerHTML = `<i class="member-dot" style="background:${member.color}">${initials(member.name)}</i>${member.name}`
303:       this.el.members.appendChild(chip)
304:     }
305:   }
