307:   renderChips(list) {
308:     this.el.chips.innerHTML = ''
309:     for (const text of list) {
310:       const chip = document.createElement('button')
311:       chip.type = 'button'
312:       chip.className = 'chat-chip'
313:       chip.textContent = text
314:       chip.addEventListener('click', () => this.send(text))
315:       this.el.chips.appendChild(chip)
316:     }
317:   }
318: 
319:   pushLocal(message) {
320:     this.messages.push(message)
321:     this.renderMessages()
322:   }
323: 
324:   renderMessages() {
325:     const log = this.el.log
326:     log.innerHTML = ''
327:     for (const message of this.messages.slice(-60)) {
328:       const author = message.author || { name: 'Unknown', color: '#8aa0b8', role: '' }
329:       const wrap = document.createElement('div')
330:       wrap.className = 'chat-msg'
331:       if (message.kind === 'system') wrap.classList.add('is-system')
332:       if (message.tone === 'good') wrap.classList.add('is-good')
333:       if (message.kind === 'mission') wrap.classList.add('is-mission')
334:       if (author.id === 'player') wrap.classList.add('is-human')
335:       wrap.innerHTML = `
336:         <div class="chat-avatar" style="background:${author.color}">${initials(author.name)}</div>
337:         <div class="chat-body">
338:           <div class="chat-meta">
339:             <span class="chat-name" style="color:${author.color}">${author.name}</span>
340:             ${author.role ? `<span class="chat-role">${author.role}</span>` : ''}
341:             <span class="chat-time">${timeLabel(message.ts || Date.now())}</span>
342:           </div>
343:           <div class="chat-text">${this.escape(message.text || '')}${message.provider === 'zen' ? '<span class="chat-provider">·llm</span>' : ''}</div>
344:         </div>`
345:       log.appendChild(wrap)
346:     }
347:     log.scrollTop = log.scrollHeight
348:   }
349: 
350:   escape(text) {
351:     return String(text).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]))
352:   }
353: 
354:   async send(raw) {
355:     const text = String(raw || '').trim()
356:     if (!text || this.mode === 'closed') return
357:     if (this.mode === 'dm' && this.dmPersona) {
358:       this.pushLocal({
359:         kind: 'chat',
360:         text,
361:         author: { id: 'player', name: 'You', role: 'Human', color: '#7bd4ff' },
362:         ts: Date.now()
363:       })
364:       this.el.input.value = ''
365:       try {
366:         const res = await fetch('/api/chat', {
367:           method: 'POST',
368:           headers: { 'Content-Type': 'application/json' },
369:           body: JSON.stringify({
370:             clientId: this.clientId,
371:             roomId: this.room.id,
372:             target: this.dmPersona.id,
373:             text
374:           })
375:         })
376:         const body = await res.json()
377:         if (body.reply) this.pushLocal(body.reply)
378:       } catch {
379:         this.pushLocal({ kind: 'system', text: 'No answer. The hub is offline.', author: { name: 'Sunset City', color: '#8aa0b8' } })
380:       }
381:       return
382:     }
383: 
384:     this.el.input.value = ''
385:     try {
386:       await fetch('/api/chat', {
387:         method: 'POST',
388:         headers: { 'Content-Type': 'application/json' },
389:         body: JSON.stringify({ clientId: this.clientId, roomId: this.room.id, text })
390:       })
391:     } catch {
392:       this.pushLocal({ kind: 'system', text: 'The hub did not answer.', author: { name: 'Sunset City', color: '#8aa0b8' } })
393:     }
394:   }
