396:   async openBoard() {
397:     this.el.boardPanel.classList.remove('is-hidden')
398:     this.pushOpen()
399:     this.el.boardStatus.textContent = 'loading...'
400:     try {
401:       const res = await fetch(`/api/missions?clientId=${encodeURIComponent(this.clientId)}`)
402:       const body = await res.json()
403:       this.board = body.board || []
404:       this.activeMission = body.active || this.activeMission
405:       this.renderBoard()
406:       this.el.boardStatus.textContent = `${this.board.length} open contracts`
407:     } catch {
408:       this.el.boardStatus.textContent = 'board offline'
409:     }
410:   }
411: 
412:   closeBoard() {
413:     this.el.boardPanel.classList.add('is-hidden')
414:     this.popOpen()
415:   }
416: 
417:   async generateMission() {
418:     this.el.boardStatus.textContent = 'posting...'
419:     try {
420:       await fetch('/api/missions/generate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
421:       await this.openBoard()
422:     } catch {
423:       this.el.boardStatus.textContent = 'the fixer is offline'
424:     }
425:   }
426: 
427:   renderBoard() {
428:     const list = this.el.boardList
429:     list.innerHTML = ''
430:     for (const mission of this.board) {
431:       const active = this.activeMission && this.activeMission.id === mission.id
432:       const card = document.createElement('div')
433:       card.className = 'board-card' + (active ? ' is-active' : '')
434:       const steps = (mission.steps || []).map((step, index) => {
435:         const done = active && index < (mission.stepIndex || 0)
436:         const current = active && index === (mission.stepIndex || 0)
437:         return `<span class="board-step ${done ? 'done' : ''} ${current ? 'active' : ''}">${step.label}</span>`
438:       }).join('')
439:       card.innerHTML = `
440:         <div class="board-card-top"><b>${mission.title}</b><span>$${mission.reward}</span></div>
441:         <div class="board-brief">${mission.brief}</div>
442:         <div class="board-steps">${steps}</div>
443:         <div class="board-meta">
444:           <span class="board-who">GIVER ${(mission.giver || '').toUpperCase()}${mission.companions && mission.companions.length ? ` · CREW ${mission.companions.join(', ').toUpperCase()}` : ''}</span>
445:           <button class="board-accept" ${active ? 'disabled' : ''}>${active ? 'ON THE JOB' : 'ACCEPT'}</button>
446:         </div>`
447:       const button = card.querySelector('.board-accept')
448:       button.addEventListener('click', () => this.acceptMission(mission))
449:       list.appendChild(card)
450:     }
451:   }
452: 
453:   async acceptMission(mission) {
454:     try {
455:       const res = await fetch('/api/missions/accept', {
456:         method: 'POST',
457:         headers: { 'Content-Type': 'application/json' },
458:         body: JSON.stringify({ clientId: this.clientId, missionId: mission.id, roomId: this.room?.id || 'el-rey' })
459:       })
460:       const body = await res.json()
461:       if (body.mission) {
462:         this.activeMission = body.mission
463:         this.onMission(body.mission)
464:         this.renderBoard()
465:         this.closeBoard()
466:         this.exitRoom()
467:       }
468:     } catch {
469:       this.el.boardStatus.textContent = 'could not accept'
470:     }
471:   }
472: 
473:   openVenues(playerPosition) {
474:     this.el.venuesPanel.classList.remove('is-hidden')
475:     this.pushOpen()
476:     this.renderVenues(playerPosition)
477:   }
478: 
479:   closeVenues() {
480:     this.el.venuesPanel.classList.add('is-hidden')
481:     this.popOpen()
482:   }
483: 
484:   renderVenues(playerPosition) {
485:     const list = this.el.venuesList
486:     list.innerHTML = ''
487:     const rows = this.rooms
488:       .map((room) => {
489:         const venue = room.venue
490:         const door = venue?.door
491:         const distance = playerPosition && door ? Math.round(Math.hypot(playerPosition.x - door.x, playerPosition.z - door.z)) : null
492:         return { room, distance }
493:       })
494:       .sort((a, b) => (a.distance ?? 9999) - (b.distance ?? 9999))
495:     for (const { room, distance } of rows) {
496:       const row = document.createElement('div')
497:       row.className = 'venue-row' + (distance !== null && distance < 30 ? ' is-near' : '')
498:       row.innerHTML = `
499:         <span class="venue-swatch" style="background:${room.accent}"></span>
500:         <span class="venue-copy"><b>${room.name}</b><small>${room.blurb || room.topic}</small></span>
501:         <span class="venue-dist">${distance === null ? '--' : `${distance}m`}</span>`
502:       row.addEventListener('click', () => {
503:         this.closeVenues()
504:         this.onPickVenue(room)
505:       })
506:       list.appendChild(row)
507:     }
508:   }
509: 
510:   say(anchor, name, text, color = '#ffd35f') {
511:     if (!anchor || !this.el.bubbleLayer) return
512:     const el = document.createElement('div')
513:     el.className = 'bubble'
514:     el.style.setProperty('--bubble-color', color)
515:     el.innerHTML = `<span class="bubble-name">${name}</span>${this.escape(text)}`
516:     this.el.bubbleLayer.appendChild(el)
517:     const bubble = { el, anchor, until: performance.now() + 5200 }
518:     this.bubbles.push(bubble)
519:     setTimeout(() => {
520:       el.classList.add('is-fading')
521:       setTimeout(() => el.remove(), 450)
522:       this.bubbles = this.bubbles.filter((b) => b !== bubble)
523:     }, 5200)
524:   }
525: 
526:   updateBubbles(camera) {
527:     if (!this.bubbles.length) return
528:     const width = window.innerWidth
529:     const height = window.innerHeight
530:     const vector = new THREE.Vector3()
531:     for (const bubble of this.bubbles) {
532:       const position = bubble.anchor?.position || bubble.anchor
533:       if (!position) continue
534:       vector.set(position.x, (position.y || 0) + 2.25, position.z)
535:       vector.project(camera)
536:       const visible = vector.z < 1
537:       bubble.el.style.display = visible ? 'block' : 'none'
538:       if (!visible) continue
